        c = new Owned();
    }

    function _run(address newOwner) internal {
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        assertTrue(reverted
            ? ownerAfter == ownerBefore && ownerBefore != newOwner
            : ownerAfter == newOwner);
    }

